import asyncio
import random
import aiohttp

ENDPOINTS = [f"https://api.example.com/v1/source/{i}" for i in range(20)]
MAX_ATTEMPTS = 4

async def fetch_with_retry(session: aiohttp.ClientSession, url: str) -> dict:
    for attempt in range(MAX_ATTEMPTS):
        try:
            async with asyncio.timeout(8):
                async with session.get(url) as resp:
                    if resp.status in (429, 500, 502, 503):
                        raise aiohttp.ClientResponseError(
                            resp.request_info, resp.history, status=resp.status
                        )
                    resp.raise_for_status()
                    return await resp.json()
        except (aiohttp.ClientError, asyncio.TimeoutError):
            if attempt == MAX_ATTEMPTS - 1:
                raise
            backoff = 0.5 * (2 ** attempt) + random.uniform(0, 0.3)
            await asyncio.sleep(backoff)  # non-blocking backoff
    raise RuntimeError("unreachable")

async def main() -> None:
    results: dict[str, dict] = {}
    async with aiohttp.ClientSession() as session:
        async with asyncio.TaskGroup() as tg:
            tasks = {
                url: tg.create_task(fetch_with_retry(session, url))
                for url in ENDPOINTS
            }
        # TaskGroup awaited all tasks on exit; results are ready
        results = {url: t.result() for url, t in tasks.items()}
    print(f"ingested {len(results)} sources successfully")

if __name__ == "__main__":
    asyncio.run(main())
